{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABlE snitch_db.maplemonk.inventory_health_stores as WITH base AS ( SELECT DISTINCT CASE WHEN UPPER(TRIM(sku_group)) LIKE \'SN%\' OR UPPER(TRIM(sku_group)) LIKE \'BP%\' THEN UPPER(TRIM(sku_group)) WHEN UPPER(TRIM(sku_group)) LIKE \'SH%\' THEN UPPER(TRIM(REGEXP_SUBSTR(sku_group::STRING, \'^[^-]+-[^-]+\'))) WHEN UPPER(TRIM(sku_group)) LIKE \'MP%\' THEN UPPER(TRIM(REGEXP_SUBSTR(sku_group::STRING, \'^[^-]+-[^-]+-[^-]+\'))) WHEN UPPER(TRIM(sku_group)) LIKE \'4C%\' THEN UPPER(TRIM(REGEXP_SUBSTR(sku_group::STRING, \'^[^-]+-[^-]+-[^-]+\'))) ELSE CASE WHEN UPPER(TRIM(sku_group)) LIKE \'%-%\' THEN UPPER(TRIM(REGEXP_SUBSTR(sku_group::STRING, \'^[^-]+-[^-]+\'))) ELSE UPPER(TRIM(sku_group)) END END AS sku_group, marketplace_mapped AS store_name, inventory, xs_units AS XS, s_units AS S, m_units AS M, l_units AS L, xl_units AS XL, xxl_units AS \"2XL\", xl3_units AS \"3XL\", xl4_units AS \"4XL\", xl5_units AS \"5XL\", xl6_units AS \"6XL\", total_sales AS sales, round(sales_last_30_days/30) AS ROS_L30 , days_since_first_order as ageing FROM snitch_db.maplemonk.offline_master WHERE sku_group IS NOT NULL ), meta_data AS ( SELECT UPPER(TRIM(sku_group)) AS sku_group, UPPER(TRIM(l1_category)) AS l1_category, CASE WHEN UPPER(TRIM(sku_group)) LIKE \'%SFS%\' THEN \'SHIRTS\' WHEN UPPER(TRIM(category)) = \'OVERSHIRT\' THEN \'OVERSHIRTS\' ELSE UPPER(TRIM(category)) END AS category, UPPER(meta1) as meta1, UPPER(meta2) as meta2, UPPER(meta3) as meta3 FROM snitch_db.maplemonk.meta_mapping_cogs_sku WHERE LOWER(TRIM(category)) NOT IN (\'(nil)\',\'default\',\'innerwear\') ), price AS ( SELECT DISTINCT CASE WHEN UPPER(TRIM(sku_group)) LIKE \'SN%\' OR UPPER(TRIM(sku_group)) LIKE \'BP%\' THEN UPPER(TRIM(sku_group)) WHEN UPPER(TRIM(sku_group)) LIKE \'SH%\' THEN UPPER(TRIM(REGEXP_SUBSTR(sku_group::STRING, \'^[^-]+-[^-]+\'))) WHEN UPPER(TRIM(sku_group)) LIKE \'MP%\' THEN UPPER(TRIM(REGEXP_SUBSTR(sku_group::STRING, \'^[^-]+-[^-]+-[^-]+\'))) WHEN UPPER(TRIM(sku_group)) LIKE \'4C%\' THEN UPPER(TRIM(REGEXP_SUBSTR(sku_group::STRING, \'^[^-]+-[^-]+-[^-]+\'))) ELSE CASE WHEN UPPER(TRIM(sku_group)) LIKE \'%-%\' THEN UPPER(TRIM(REGEXP_SUBSTR(sku_group::STRING, \'^[^-]+-[^-]+\'))) ELSE UPPER(TRIM(sku_group)) END END AS sku_group, price FROM snitch_db.maplemonk.horizontal_sales_categories ), eoss_bf AS ( SELECT sku_group, eoss, bf FROM snitch_db.maplemonk.eoss_bf WHERE sku_group IS NOT NULL ), sales AS ( SELECT CASE WHEN UPPER(TRIM(sku_group)) LIKE \'SN%\' OR UPPER(TRIM(sku_group)) LIKE \'BP%\' THEN UPPER(TRIM(sku_group)) WHEN UPPER(TRIM(sku_group)) LIKE \'MP%\' THEN UPPER(TRIM(REGEXP_SUBSTR(sku_group::STRING, \'^[^-]+-[^-]+-[^-]+\'))) ELSE CASE WHEN UPPER(TRIM(sku_group)) LIKE \'%-%\' THEN UPPER(TRIM(REGEXP_SUBSTR(sku_group::STRING, \'^[^-]+-[^-]+\'))) ELSE UPPER(TRIM(sku_group)) END END AS sku_group, SUM(CASE WHEN UPPER(TRIM(type)) = \'STORE\' THEN gross_sales ELSE 0 END) AS offline_sales_value FROM snitch_db.maplemonk.horizontal_sales_categories WHERE sku_group IS NOT NULL GROUP BY 1 ), final_calc AS ( SELECT b.sku_group, b.ageing, b.store_name, md.l1_category, md.category, md.meta1, md.meta2, md.meta3, eb.eoss, eb.bf, b.inventory, b.XS, b.S, b.M, b.L, b.XL, b.\"2XL\", b.\"3XL\", b.\"4XL\", b.\"5XL\", b.\"6XL\", CASE WHEN b.sku_group LIKE \'%4MBG%\' THEN GREATEST( LEAST( ROUND((COALESCE(b.\"3XL\",0) - 1) / 3), ROUND((COALESCE(b.\"4XL\",0) - 1) / 3), ROUND((COALESCE(b.\"5XL\",0) - 1) / 2), ROUND((COALESCE(b.\"6XL\",0) - 1) / 2) ), 0 ) ELSE GREATEST( LEAST( ROUND((COALESCE(b.S,0) - 2) / 2), ROUND((COALESCE(b.M,0) - 2) / 4), ROUND((COALESCE(b.L,0) - 2) / 4), ROUND((COALESCE(b.XL,0) - 2) / 2) ), 0 ) END AS full_size_options, b.ROS_L30, p.price, b.sales, s.offline_sales_value FROM base b LEFT JOIN meta_data md ON md.sku_group = b.sku_group LEFT JOIN eoss_bf eb ON b.sku_group = eb.sku_group LEFT JOIN sales s ON b.sku_group = s.sku_group LEFT JOIN price p ON b.sku_group = p.sku_group WHERE b.sku_group IS NOT NULL ) SELECT sku_group, store_name, l1_category, category, meta1, meta2, meta3, eoss, bf, ageing, inventory, XS, S, M, L, XL, \"2XL\", \"3XL\", \"4XL\", \"5XL\", \"6XL\", full_size_options, CASE WHEN sku_group LIKE \'%4MBG%\' THEN full_size_options * 10 ELSE full_size_options * 12 END AS full_size_inv, CASE WHEN full_size_options >= 1 THEN \'full_size\' ELSE \'cut_size\' END AS size_flag, ROS_L30, sales as offline_sales_qty, price*offline_sales_qty as offline_sales_value, FROM final_calc;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            